css:
.maisonsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c1a17;
    background: linear-gradient(165deg, #f6f1e9 0%, #efe7da 100%);
    border-radius: 4px;
}

.maisonsim-container * {
    box-sizing: border-box;
}

.maisonsim-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #14110d 0%, #221c14 60%, #2e2618 100%);
    color: #f4ecdd;
    border-radius: 4px;
    margin-bottom: 22px;
    border: 1px solid #3a3120;
    box-shadow: 0 14px 38px rgba(20, 17, 13, 0.30);
}

.maisonsim-header h1 {
    margin: 10px 0 12px;
    font-family: 'Didot', 'Bodoni MT', Georgia, 'Times New Roman', serif;
    font-size: 2.7rem;
    font-weight: 600;
    letter-spacing: 5px;
    text-transform: uppercase;
    color: #f4ecdd;
}

.maisonsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-weight: 600;
    color: #d8b863;
    background: rgba(216, 184, 99, 0.10);
    border: 1px solid rgba(216, 184, 99, 0.35);
    padding: 5px 16px;
    border-radius: 2px;
}

.maisonsim-subtitle {
    margin: 4px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.6;
    color: #ddd2bd;
    font-style: italic;
}

.maisonsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.94rem;
    font-weight: 600;
    color: #3a3120;
    margin-bottom: 18px;
    padding: 6px 4px;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.maisonsim-period-counter #currentDay,
.maisonsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14110d;
}

.maisonsim-round-name {
    background: #14110d;
    color: #d8b863;
    padding: 3px 14px;
    border-radius: 2px;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 1.2px;
    margin-left: 4px;
}

.maisonsim-clock {
    margin-left: auto;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.8px;
    color: #8a2b1e;
    background: #f3e0da;
    padding: 4px 14px;
    border-radius: 2px;
}

.maisonsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.maisonsim-status-card {
    background: #fffdf8;
    border-radius: 3px;
    padding: 16px 16px 14px;
    border: 1px solid #e2d6bf;
    box-shadow: 0 4px 14px rgba(20, 17, 13, 0.06);
    border-top: 3px solid #d8b863;
}

.maisonsim-card-sellthrough { border-top-color: #6c7a3a; }
.maisonsim-card-heat { border-top-color: #a8431f; }
.maisonsim-card-governance { border-top-color: #4a5d80; }
.maisonsim-card-contingency { border-top-color: #b08a2b; }

.maisonsim-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8a7c63;
}

.maisonsim-value {
    font-family: 'Didot', 'Bodoni MT', Georgia, 'Times New Roman', serif;
    font-size: 2.5rem;
    font-weight: 600;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14110d;
}

.maisonsim-card-sellthrough .maisonsim-value { color: #5a6630; }
.maisonsim-card-heat .maisonsim-value { color: #a8431f; }
.maisonsim-card-governance .maisonsim-value { color: #4a5d80; }
.maisonsim-card-contingency .maisonsim-value { color: #9a7a26; }

.maisonsim-sublabel {
    font-size: 0.74rem;
    color: #8a7c63;
    line-height: 1.35;
}

.maisonsim-sellthrough-fail .maisonsim-value { color: #b03a26; }
.maisonsim-sellthrough-target .maisonsim-value { color: #5a6630; }

.maisonsim-contingency-blown { border-top-color: #b03a26; }
.maisonsim-contingency-blown .maisonsim-value { color: #b03a26; }

.maisonsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14110d;
    color: #f4ecdd;
    padding: 11px 20px;
    border-radius: 3px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.86rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    border: 1px solid #3a3120;
}

.maisonsim-budget-bar #budgetDisplay {
    font-family: 'Didot', 'Bodoni MT', Georgia, serif;
    font-size: 1.15rem;
    letter-spacing: 0.4px;
    color: #d8b863;
    text-transform: none;
}

.maisonsim-briefing {
    display: flex;
    gap: 16px;
    background: #fffdf8;
    border-left: 4px solid #d8b863;
    border-radius: 3px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 17, 13, 0.05);
}

.maisonsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.maisonsim-briefing-title {
    font-family: 'Didot', 'Bodoni MT', Georgia, serif;
    font-weight: 600;
    font-size: 1.18rem;
    letter-spacing: 0.4px;
    color: #14110d;
    margin-bottom: 7px;
}

.maisonsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #3a342a;
}

.maisonsim-briefing-text strong { color: #5a6630; }
.maisonsim-briefing-text em { color: #a8431f; font-style: italic; }

.maisonsim-controls {
    background: #fffdf8;
    border-radius: 3px;
    padding: 22px 24px;
    margin-bottom: 18px;
    border: 1px solid #e2d6bf;
    box-shadow: 0 4px 14px rgba(20, 17, 13, 0.06);
}

.maisonsim-controls h3 {
    margin: 0 0 16px;
    font-family: 'Didot', 'Bodoni MT', Georgia, serif;
    font-size: 1.22rem;
    font-weight: 600;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #14110d;
    border-bottom: 1px solid #e2d6bf;
    padding-bottom: 10px;
}

.maisonsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.9rem;
    color: #2b261d;
    margin: 16px 0 6px;
    line-height: 1.45;
}

.maisonsim-container select,
.maisonsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d2c3a3;
    border-radius: 3px;
    font-size: 0.92rem;
    background-color: #fbf7ee;
    color: #1c1a17;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.maisonsim-container select:focus,
.maisonsim-container input[type="number"]:focus {
    outline: none;
    border-color: #d8b863;
    box-shadow: 0 0 0 3px rgba(216, 184, 99, 0.22);
}

.maisonsim-container select option {
    background-color: #fffdf8;
    color: #1c1a17;
}

.maisonsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #a8431f;
}

.maisonsim-range-readout,
.maisonsim-alloc-readout {
    font-size: 0.86rem;
    font-weight: 700;
    color: #6c5f48;
    margin-top: 6px;
}

.maisonsim-range-readout span:last-child,
.maisonsim-alloc-readout span:nth-child(2) {
    color: #a8431f;
    font-weight: 800;
}

.maisonsim-hint {
    font-size: 0.79rem;
    color: #8a7c63;
    margin-top: 5px;
    line-height: 1.45;
    font-style: italic;
}

.maisonsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.maisonsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f0e2;
    border: 1px solid #e2d6bf;
    border-radius: 3px;
    padding: 9px 13px;
}

.maisonsim-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #2b261d;
}

.maisonsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.maisonsim-container .btn {
    margin-top: 20px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
}

.maisonsim-container .btn-primary {
    background: linear-gradient(135deg, #14110d 0%, #2e2618 100%);
    border: 1px solid #d8b863;
    color: #f4ecdd;
    padding: 12px 30px;
    border-radius: 3px;
    box-shadow: 0 6px 16px rgba(20, 17, 13, 0.28);
}

.maisonsim-container .btn-primary:hover {
    background: linear-gradient(135deg, #2e2618 0%, #3a3120 100%);
    color: #d8b863;
}

.maisonsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d2c3a3;
    color: #6c5f48;
}

.maisonsim-coach {
    background: #14110d;
    color: #ece1cc;
    border-radius: 3px;
    padding: 18px 22px;
    margin-bottom: 18px;
    border: 1px solid #3a3120;
    box-shadow: 0 6px 18px rgba(20, 17, 13, 0.22);
}

.maisonsim-coach-header {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.6px;
    font-weight: 700;
    color: #d8b863;
    margin-bottom: 9px;
}

.maisonsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.maisonsim-coach-body strong { color: #e6c878; }
.maisonsim-coach-body em { color: #e0a98f; font-style: italic; }

.maisonsim-history,
.maisonsim-chart {
    background: #fffdf8;
    border-radius: 3px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2d6bf;
    box-shadow: 0 4px 14px rgba(20, 17, 13, 0.06);
}

.maisonsim-history h3,
.maisonsim-chart h3 {
    margin: 0 0 14px;
    font-family: 'Didot', 'Bodoni MT', Georgia, serif;
    font-size: 1.18rem;
    font-weight: 600;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: #14110d;
}

.maisonsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.87rem;
    color: #2b261d;
}

.maisonsim-container table#usfHistoryTable th {
    background: #f3ead8;
    color: #14110d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.6px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d6bf;
}

.maisonsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e8d8;
}

.maisonsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf5ea;
}

.maisonsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .maisonsim-container {
        padding: 14px;
    }
    .maisonsim-header h1 {
        font-size: 1.9rem;
        letter-spacing: 3px;
    }
    .maisonsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .maisonsim-value {
        font-size: 2rem;
    }
    .maisonsim-clock {
        margin-left: 0;
    }
    .maisonsim-period-counter {
        font-size: 0.84rem;
    }
    .maisonsim-budget-bar {
        flex-direction: column;
        gap: 5px;
        align-items: flex-start;
    }
    .maisonsim-alloc-row {
        flex-wrap: wrap;
    }
    .maisonsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .maisonsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (dark-on-light for the framework's white modal) ===== */
.maisonsim-cm { text-align: center; color: #2c2620; padding: 8px 4px 4px; }
.maisonsim-cm-title { font-size: 1.05rem; font-weight: 700; color: #6b5836; margin-bottom: 10px; }
.maisonsim-cm-scorewrap { margin: 4px 0 6px; }
.maisonsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #6b5836; }
.maisonsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8a7c63; }
.maisonsim-cm-scorelabel { font-size: .78rem; text-transform: uppercase; letter-spacing: .05em; color: #8a7c63; }
.maisonsim-cm-grade { font-size: 1.3rem; font-weight: 700; color: #2c2620; margin: 6px 0; }
.maisonsim-cm-badges { margin: 8px 0 12px; }
.maisonsim-cm-badge { display: inline-block; padding: 5px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700; }
.maisonsim-cm-badge-ok { background: #e8e0cc; color: #6b5320; border: 1px solid #a08842; }
.maisonsim-cm-badge-fail { background: #f3d9d3; color: #8f2418; border: 1px solid #b8402f; }
.maisonsim-cm-badge-warn { background: #f6ead2; color: #856016; border: 1px solid #c99a34; }
.maisonsim-cm-kpis { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin: 10px 0; }
.maisonsim-cm-kpi { background: #f4f0e8; border: 1px solid #e5ddcd; border-radius: 10px; padding: 10px 14px; min-width: 96px; }
.maisonsim-cm-kpi-n { font-size: 1.5rem; font-weight: 800; color: #6b5836; }
.maisonsim-cm-kpi-l { font-size: .72rem; text-transform: uppercase; letter-spacing: .03em; color: #8a7c63; }
.maisonsim-cm-insights { text-align: left; margin: 12px auto 2px; max-width: 560px; background: #faf7f0; border: 1px solid #ece4d3; border-radius: 10px; padding: 10px 14px; }
.maisonsim-cm-insights-h { font-weight: 700; color: #6b5836; margin-bottom: 6px; font-size: .9rem; }
.maisonsim-cm-insights ul { margin: 0; padding-left: 18px; }
.maisonsim-cm-insights li { color: #3d352b; font-size: .88rem; margin-bottom: 4px; }

