(function() {
    'use strict';

    class MaisonAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Creative Director — A Season at Maison Lievre`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_SELLTHROUGH = 38;     // last season, critically praised
            this.TARGET_SELLTHROUGH = 62;    // board target this season
            this.HEALTHY_SELLTHROUGH = 67;   // segment healthy band 65-70
            this.START_HEAT = 20;            // brand heat starts low, big headroom
            this.START_GOVERNANCE = 15;      // no repeatable process yet
            this.BUDGET_CAP = 2400;          // EUR 2.4M, in EUR thousands
            this.OVERRUN_COST = 432;         // 18% atelier overrun lands in Round 3 (~430k)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    sellthrough: this.START_SELLTHROUGH,
                    heat: this.START_HEAT,
                    governance: this.START_GOVERNANCE,
                    budgetUsed: 0,
                    contingency: 0,
                    overrunForced: false,
                    paperShow: false,
                    sellthroughHistory: [this.START_SELLTHROUGH],
                    heatHistory: [this.START_HEAT],
                    governanceHistory: [this.START_GOVERNANCE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    thesis: `optimal`,
                    commercial: 60,
                    statement: 30,
                    radical: 10,
                    constraint: `sellthrough`,
                    showSplit: `balanced`,
                    statementSpend: 650,
                    commercialSpend: 1300,
                    contingency: 450,
                    method: `panel`,
                    radicalLook: `keep`,
                    discipline: 70,
                    interpret: `dual`,
                    process: `codified`,
                    governanceMove: `charter`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`thesisInput`);
                const co = document.getElementById(`commercialInput`);
                const st = document.getElementById(`statementInput`);
                const ra = document.getElementById(`radicalInput`);
                const cn = document.getElementById(`constraintInput`);
                if (th) decisions.thesis = th.value;
                if (cn) decisions.constraint = cn.value;
                if (co) decisions.commercial = parseFloat(co.value);
                if (st) decisions.statement = parseFloat(st.value);
                if (ra) decisions.radical = parseFloat(ra.value);
                const parts = [decisions.commercial, decisions.statement, decisions.radical];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_mix_negative`); return false;
                }
                const total = Math.round(decisions.commercial + decisions.statement + decisions.radical);
                if (total !== 100) {
                    warn(`warn_mix_total`); return false;
                }
            } else if (round === 2) {
                const sh = document.getElementById(`showSplitInput`);
                const ss = document.getElementById(`statementSpendInput`);
                const cs = document.getElementById(`commercialSpendInput`);
                const ct = document.getElementById(`contingencyInput`);
                if (sh) decisions.showSplit = sh.value;
                if (ss) decisions.statementSpend = parseFloat(ss.value);
                if (cs) decisions.commercialSpend = parseFloat(cs.value);
                if (ct) decisions.contingency = parseFloat(ct.value);
                const spends = [decisions.statementSpend, decisions.commercialSpend, decisions.contingency];
                if (spends.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_spend_negative`); return false;
                }
                const allocated = decisions.statementSpend + decisions.commercialSpend + decisions.contingency;
                if (allocated > this.BUDGET_CAP + 0.001) {
                    warn(`warn_budget_over`); return false;
                }
            } else if (round === 3) {
                const me = document.getElementById(`methodInput`);
                const rl = document.getElementById(`radicalLookInput`);
                const di = document.getElementById(`disciplineInput`);
                if (me) decisions.method = me.value;
                if (rl) decisions.radicalLook = rl.value;
                if (di) decisions.discipline = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.discipline) || decisions.discipline < 0 || decisions.discipline > 100) {
                    warn(`warn_discipline_range`); return false;
                }
            } else if (round === 4) {
                const ip = document.getElementById(`interpretInput`);
                const pr = document.getElementById(`processInput`);
                const gm = document.getElementById(`governanceMoveInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ip) decisions.interpret = ip.value;
                if (pr) decisions.process = pr.value;
                if (gm) decisions.governanceMove = gm.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: sell = full-price sell-through points; heat = editorial pull / novelty;
            // gov = repeatable defensible creative governance.
            let sellDelta = 0, heatDelta = 0, govDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Thesis: optimal newness manages the tension; reinvention chases the show;
                // reassurance protects margin and mortgages the brand.
                if (d.thesis === `optimal`) {
                    sellDelta += 7; heatDelta += 9; govDelta += 6; coachKey = `coach_r1_optimal`;
                } else if (d.thesis === `radical`) {
                    sellDelta -= 8; heatDelta += 12; govDelta -= 2; coachKey = `coach_r1_radical`;
                } else {
                    sellDelta += 10; heatDelta -= 10; govDelta -= 2; coachKey = `coach_r1_safe`;
                }

                // Novelty mix: optimal newness sits commercial 50-65 / statement 25-35 / radical 5-15.
                // Too much statement+radical repeats last season's 38%; too little kills the heat.
                const noveltyHeavy = (d.statement + d.radical);
                const inOptimalBand = d.commercial >= 50 && d.commercial <= 65 &&
                    d.statement >= 25 && d.statement <= 35 && d.radical >= 5 && d.radical <= 15;
                if (inOptimalBand) {
                    sellDelta += 9; heatDelta += 9; govDelta += 4;
                    if (d.thesis === `optimal`) coachKey = `coach_r1_optimalmix`;
                } else if (noveltyHeavy >= 60) {
                    // Maximising novelty (Common Error 1): editorial heat but the sell-through trap.
                    sellDelta -= 12; heatDelta += 10; coachKey = `coach_r1_noveltyheavy`;
                } else if (noveltyHeavy <= 20) {
                    // Over-correcting to safe (Common Error 2): margin now, no heat, brand erodes.
                    sellDelta += 8; heatDelta -= 12; coachKey = `coach_r1_safemix`;
                } else {
                    sellDelta += 2; heatDelta += 2;
                }

                // Binding constraint: this season the PE board hired you to fix sell-through.
                if (d.constraint === `sellthrough`) { sellDelta += 5; govDelta += 4; }
                else if (d.constraint === `editorial`) { sellDelta -= 5; heatDelta += 3; coachKey = `coach_r1_editorial`; }
                else { govDelta -= 3; coachKey = `coach_r1_budget`; }

                summaryKey = (d.thesis === `optimal` && inOptimalBand && d.constraint === `sellthrough`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the EUR 2.4M as a portfolio (Common Errors 2 & 3).
                ds.budgetUsed = Math.round(d.statementSpend + d.commercialSpend + d.contingency);
                ds.contingency = Math.round(d.contingency);

                // Show vs product: a focused product-led show frames the statement looks;
                // spectacle burns budget chasing the runway; a bare show wastes the moment.
                switch (d.showSplit) {
                    case `balanced`: heatDelta += 6; sellDelta += 4; govDelta += 3; coachKey = `coach_r2_balanced`; break;
                    case `spectacle`: heatDelta += 8; sellDelta -= 6; coachKey = `coach_r2_spectacle`; break;
                    case `minimal`: heatDelta -= 8; sellDelta += 2; coachKey = `coach_r2_minimal`; break;
                }

                // Statement vs commercial spend: statement funds the editorial, commercial funds
                // the season. The sell-through engine (commercial) must be well funded.
                const productSpend = d.statementSpend + d.commercialSpend;
                const statementShare = productSpend > 0 ? d.statementSpend / productSpend : 0;
                if (statementShare >= 0.55) {
                    // Too much on costly statement/radical pieces — starves the volume engine.
                    sellDelta -= 10; heatDelta += 7; coachKey = `coach_r2_statementheavy`;
                } else if (statementShare <= 0.18) {
                    // Almost no statement spend — no editorial, brand goes invisible.
                    sellDelta += 5; heatDelta -= 9; coachKey = `coach_r2_commercialheavy`;
                } else {
                    sellDelta += 7; heatDelta += 6;
                }
                if (d.commercialSpend >= 1100) { sellDelta += 4; }

                // Contingency for the warned 18% atelier overrun (~432k). Protecting it is
                // budget discipline as a precondition for creative freedom (Common Error 3).
                if (d.contingency >= this.OVERRUN_COST) {
                    govDelta += 9; sellDelta += 2;
                    if (d.showSplit === `balanced`) coachKey = `coach_r2_contingency`;
                } else if (d.contingency >= 200) {
                    govDelta += 3; coachKey = `coach_r2_thincontingency`;
                } else {
                    govDelta -= 8; coachKey = `coach_r2_nocontingency`;
                }

                summaryKey = (d.showSplit === `balanced` && statementShare > 0.18 && statementShare < 0.55 && d.contingency >= this.OVERRUN_COST) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Evaluate & select the designs (Common Errors 4 & 5).
                // Evaluation method: a defensible, explicit gate beats selecting by feel.
                switch (d.method) {
                    case `panel`: sellDelta += 8; heatDelta += 6; govDelta += 14; coachKey = `coach_r3_panel`; break;
                    case `data`: sellDelta += 11; heatDelta -= 4; govDelta += 8; coachKey = `coach_r3_data`; break;
                    case `curatorial`: sellDelta -= 4; heatDelta += 8; govDelta -= 4; coachKey = `coach_r3_curatorial`; break;
                    case `feel`: sellDelta -= 6; heatDelta += 2; govDelta -= 14; coachKey = `coach_r3_feel`; break;
                }

                // The radical show-anchor look: value it on portfolio editorial pull, not standalone
                // margin (Common Error 5). Keeping or modifying it preserves the signal that pulls
                // demand to the commercial pieces; cutting it on sell-through alone kills the heat.
                switch (d.radicalLook) {
                    case `keep`: heatDelta += 12; sellDelta -= 2; govDelta += 4; coachKey = (d.method === `panel`) ? `coach_r3_keep` : coachKey; break;
                    case `modify`: heatDelta += 9; sellDelta += 6; govDelta += 6; coachKey = (d.method === `panel` || d.method === `data`) ? `coach_r3_modify` : coachKey; break;
                    case `cut`: heatDelta -= 12; sellDelta += 3; coachKey = `coach_r3_cut`; break;
                }

                // Discipline to the agreed mix & sell-through target while selecting.
                if (d.discipline >= 60) { sellDelta += 7; govDelta += 5; }
                else if (d.discipline <= 25) { sellDelta -= 6; govDelta -= 6; coachKey = `coach_r3_nodiscipline`; }

                // The atelier overrun lands now. With contingency it is absorbed; without it,
                // a creative cut is forced for cash reasons (Common Error 3 bites here).
                if (ds.contingency >= this.OVERRUN_COST) {
                    ds.contingency = Math.round(ds.contingency - this.OVERRUN_COST);
                    govDelta += 4;
                } else {
                    ds.overrunForced = true;
                    sellDelta -= 9; heatDelta -= 9; govDelta -= 6;
                    ds.budgetUsed = Math.min(this.BUDGET_CAP, ds.budgetUsed + (this.OVERRUN_COST - ds.contingency));
                    ds.contingency = 0;
                    coachKey = `coach_r3_overrun`;
                }

                summaryKey = ((d.method === `panel` || d.method === `data`) && (d.radicalLook === `keep` || d.radicalLook === `modify`) && d.discipline >= 60) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Show, reception & next season — sustain reputation AND commerce (Common Error mix).
                switch (d.interpret) {
                    case `dual`: sellDelta += 5; heatDelta += 5; govDelta += 10; coachKey = `coach_r4_dual`; break;
                    case `commerce`: heatDelta -= 6; govDelta += 2; coachKey = `coach_r4_commerce`; break;
                    case `acclaim`: sellDelta -= 6; govDelta -= 4; coachKey = `coach_r4_acclaim`; break;
                }

                // A repeatable creativity-evaluation process for future seasons.
                switch (d.process) {
                    case `codified`: govDelta += 16; sellDelta += 3; heatDelta += 3; break;
                    case `dataonly`: govDelta += 4; heatDelta -= 8; coachKey = `coach_r4_dataonly`; break;
                    case `instinct`: govDelta -= 14; coachKey = `coach_r4_instinct`; break;
                }

                // Governing the founder-grandson / PE interface.
                switch (d.governanceMove) {
                    case `charter`: govDelta += 12; sellDelta += 4; heatDelta += 4; coachKey = (d.process === `codified`) ? `coach_r4_charter` : coachKey; break;
                    case `ceo`: govDelta -= 4; heatDelta -= 8; sellDelta += 3; coachKey = `coach_r4_ceo`; break;
                    case `founder`: govDelta -= 10; sellDelta -= 6; coachKey = `coach_r4_founder`; break;
                }

                // Conviction nudges governance.
                govDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.interpret === `dual` && d.process === `codified` && d.governanceMove === `charter`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with floors/caps. Sell-through can exceed the 62% target up toward the
            // healthy band; heat & governance run 0-100 with headroom kept for late rounds.
            ds.sellthrough = Math.max(0, Math.min(100, ds.sellthrough + sellDelta));
            ds.heat = Math.max(0, Math.min(100, ds.heat + heatDelta));
            ds.governance = Math.max(0, Math.min(100, ds.governance + govDelta));

            // Paper show: lots of editorial heat but the sell-through stayed near last season —
            // the exact 38% failure mode the board hired the Creative Director to fix.
            if (round >= 3 && ds.heat >= 55 && ds.sellthrough < 50) ds.paperShow = true;

            ds.sellthroughHistory.push(Math.round(ds.sellthrough));
            ds.heatHistory.push(Math.round(ds.heat));
            ds.governanceHistory.push(Math.round(ds.governance));

            // v1.1.0 FIX — persist the composite where the grading/reporting layer reads it
            // (express_resolveDomainScore -> domainState.performance.overallScore), every period.
            const overallScore = this._composite(ds);
            ds.performance = { overallScore: overallScore };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                sellthrough: Math.round(ds.sellthrough),
                sellDelta: Math.round(sellDelta),
                heat: Math.round(ds.heat),
                heatDelta: Math.round(heatDelta),
                governance: Math.round(ds.governance),
                govDelta: Math.round(govDelta),
                budgetUsed: ds.budgetUsed,
                contingency: ds.contingency,
                overrunForced: ds.overrunForced,
                paperShow: ds.paperShow,
                score: overallScore,
                overallScore: overallScore,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`sellthroughDisplay`, `domainState.sellthrough`, (v) => {
                const card = document.querySelector(`.maisonsim-card-sellthrough`);
                if (card) {
                    card.classList.toggle(`maisonsim-sellthrough-target`, Number(v) >= this.TARGET_SELLTHROUGH);
                    card.classList.toggle(`maisonsim-sellthrough-fail`, Number(v) < this.TARGET_SELLTHROUGH);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`heatDisplay`, `domainState.heat`, (v) => Math.round(v));
            uiManager.bind(`governanceDisplay`, `domainState.governance`, (v) => Math.round(v));
            uiManager.bind(`contingencyDisplay`, `domainState.contingency`, (v) => {
                const card = document.querySelector(`.maisonsim-card-contingency`);
                if (card) card.classList.toggle(`maisonsim-contingency-blown`, !!this._stateOverrun());
                return this._money(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => this._money(Number(v)) + ` / ` + this._money(this.BUDGET_CAP));

            const self = this;

            // Discipline slider readout.
            const di = document.getElementById(`disciplineInput`);
            const diReadout = document.getElementById(`disciplineReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }

            // Round 1 novelty-mix live total.
            const mixIds = [`commercialInput`, `statementInput`, `radicalInput`];
            const mixReadout = document.getElementById(`mixReadout`);
            const recomputeMix = function() {
                let total = 0;
                mixIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (mixReadout) mixReadout.textContent = total;
                const bar = document.querySelector(`#round1Panel .maisonsim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#b03a26` : ``;
            };
            mixIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeMix);
            });
            recomputeMix();

            // Round 2 budget allocation live total.
            const spendIds = [`statementSpendInput`, `commercialSpendInput`, `contingencyInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recomputeAlloc = function() {
                let total = 0;
                spendIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`#round2Panel .maisonsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP) ? `#b03a26` : ``;
            };
            spendIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recomputeAlloc);
            });
            recomputeAlloc();
        }

        // Locale-aware EUR formatter: English "€2.4M" / "€700k"; Spanish "2,4 M€" / "700 k€".
        _money(thousands) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const k = Math.round(Number(thousands) || 0);
            if (lang === `es`) {
                if (Math.abs(k) >= 1000) {
                    const m = (k / 1000).toFixed(1).replace(`.`, `,`).replace(/,0$/, ``);
                    return m + ` M€`;
                }
                return k + ` k€`;
            }
            if (Math.abs(k) >= 1000) {
                const m = (k / 1000).toFixed(1).replace(/\.0$/, ``);
                return `€` + m + `M`;
            }
            return `€` + k + `k`;
        }

        _stateOverrun() {
            const st = window.mySimulation && window.mySimulation.state;
            return st && st.domainState && st.domainState.overrunForced;
        }

        // v1.1.0 — composite 0-100 the reporting layer reads (formula identical to
        // getPerformanceSummary; sellthrough capped at 100). Clamped defensively.
        _composite(ds) {
            const sellthrough = Math.round(ds.sellthrough);
            const heat = Math.round(ds.heat);
            const governance = Math.round(ds.governance);
            return Math.max(0, Math.min(100, Math.round(Math.min(100, sellthrough) * 0.40 + heat * 0.30 + governance * 0.30)));
        }

        // v1.1.0 — safe i18n lookup with English fallback (chart/legend chrome).
        _cl(key, fallback) {
            try {
                const s = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
                return (s && s !== key) ? s : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
                maisonChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_sell`, `Full-Price Sell-Through %`),
                                data: [],
                                borderColor: `#5a6630`,
                                backgroundColor: `rgba(108,122,58,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#5a6630`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_heat`, `Brand Heat`),
                                data: [],
                                borderColor: `#a8431f`,
                                backgroundColor: `rgba(168,67,31,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#a8431f`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_gov`, `Creative Governance`),
                                data: [],
                                borderColor: `#4a5d80`,
                                backgroundColor: `rgba(74,93,128,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4a5d80`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#2b261d`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a7c63` }, grid: { color: `rgba(20,17,13,0.08)` },
                                title: { display: true, text: this._cl(`axis_scale`, `0–100 / %`), color: `#8a7c63` }
                            },
                            x: {
                                ticks: { color: `#8a7c63` }, grid: { color: `rgba(20,17,13,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#8a7c63` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.sellthroughHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                maisonChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.sellthroughHistory },
                        { data: ds.heatHistory },
                        { data: ds.governanceHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sellthrough = Math.round(ds.sellthrough);
            const heat = Math.round(ds.heat);
            const governance = Math.round(ds.governance);

            const hitTarget = sellthrough >= this.TARGET_SELLTHROUGH;
            const realHeat = heat >= 55;
            const paper = ds.paperShow || (heat >= 60 && sellthrough < 50);
            const composite = this._composite(ds);

            let gradeKey = `grade_another`;
            if (hitTarget && realHeat && governance >= 60 && composite >= 70) gradeKey = `grade_optimal`;
            else if (hitTarget && realHeat) gradeKey = `grade_acclaim`;
            else if (!hitTarget && realHeat) gradeKey = `grade_runway`;
            else if (hitTarget && !realHeat) gradeKey = `grade_safe`;
            else if (sellthrough > this.START_SELLTHROUGH + 10) gradeKey = `grade_short`;
            const performance = window.mySimulation.t(gradeKey);

            const insights = [];
            if (hitTarget && realHeat) insights.push(window.mySimulation.t(`insight_optimal`));
            else if (!hitTarget && realHeat) insights.push(window.mySimulation.t(`insight_runway`));
            else if (hitTarget && !realHeat) insights.push(window.mySimulation.t(`insight_safe`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (governance < 45) insights.push(window.mySimulation.t(`insight_nogov`));
            if (ds.overrunForced) insights.push(window.mySimulation.t(`insight_overrun`));
            if (sellthrough >= this.HEALTHY_SELLTHROUGH) insights.push(window.mySimulation.t(`insight_healthy`));
            if (hitTarget && realHeat && governance >= 60) insights.push(window.mySimulation.t(`insight_repeatable`));

            return {
                sellthrough: sellthrough,
                heat: heat,
                governance: governance,
                hitTarget: hitTarget,
                paper: paper,
                composite: composite,
                performance: performance,
                gradeKey: gradeKey,
                passed: (hitTarget && realHeat),
                insights: insights
            };
        }

        // v1.1.0 FIX — real completion modal (score / localized grade / MET or distinct-failure
        // badge / KPI strip / insights). Replaces the framework's generic fallback.
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            const s = summary || {};
            const score = Number.isFinite(s.composite) ? s.composite : 0;
            const grade = s.performance || t(s.gradeKey || `grade_another`);
            const passed = !!s.passed;
            const k = (v) => Math.round(v != null ? v : 0);
            let badge;
            if (passed) {
                badge = `<span class="maisonsim-cm-badge maisonsim-cm-badge-ok">\u2713 ` + t(`cm_met`) + `</span>`;
            } else if (s.paper) {
                badge = `<span class="maisonsim-cm-badge maisonsim-cm-badge-fail">\u2715 ` + t(`cm_fail_paper`) + `</span>`;
            } else {
                badge = `<span class="maisonsim-cm-badge maisonsim-cm-badge-warn">\u2022 ` + t(`cm_missed`) + `</span>`;
            }
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightHtml = insights.length
                ? `<div class="maisonsim-cm-insights"><div class="maisonsim-cm-insights-h">` + t(`cm_insights`) + `</div><ul>` + insights.map((x) => `<li>` + x + `</li>`).join(``) + `</ul></div>`
                : ``;
            return `
                <div class="maisonsim-cm">
                    <div class="maisonsim-cm-title">` + t(`cm_title`) + `</div>
                    <div class="maisonsim-cm-scorewrap">
                        <div class="maisonsim-cm-score">` + score + `<span class="maisonsim-cm-score-max">/100</span></div>
                        <div class="maisonsim-cm-scorelabel">` + t(`cm_score_of`) + `</div>
                    </div>
                    <div class="maisonsim-cm-grade">` + grade + `</div>
                    <div class="maisonsim-cm-badges">` + badge + `</div>
                    <div class="maisonsim-cm-kpis">
                        <div class="maisonsim-cm-kpi"><div class="maisonsim-cm-kpi-n">` + k(s.sellthrough) + `%</div><div class="maisonsim-cm-kpi-l">` + t(`cm_sell`) + `</div></div>
                        <div class="maisonsim-cm-kpi"><div class="maisonsim-cm-kpi-n">` + k(s.heat) + `</div><div class="maisonsim-cm-kpi-l">` + t(`cm_heat`) + `</div></div>
                        <div class="maisonsim-cm-kpi"><div class="maisonsim-cm-kpi-n">` + k(s.governance) + `</div><div class="maisonsim-cm-kpi-l">` + t(`cm_gov`) + `</div></div>
                    </div>
                    ` + insightHtml + `
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.paperShow) return window.mySimulation.t(`hint_paper`);
            if (ds.overrunForced) return window.mySimulation.t(`hint_overrun`);
            if (ds.heat < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_invisible`);
            if (state.currentPeriod >= 3 && ds.sellthrough < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.sellthrough >= this.TARGET_SELLTHROUGH && ds.heat >= 55 && ds.governance >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.sellthrough`, label: `Sell-Through`, i18nKey: `col_sellthrough`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.heat`, label: `Heat`, i18nKey: `col_heat`, formatter: (v) => Math.round(v) },
                { key: `results.governance`, label: `Governance`, i18nKey: `col_governance`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Creative Director`,
